inline U binary_rank(std::vector<Bits> rows,U columns){std::array<Bits,128> basis{};U rank=0;for(auto r:rows)for(U j=0;j<columns;++j)if(r[j]){if(basis[j].any())r^=basis[j];else{basis[j]=r;++rank;break;}}return rank;}
inline bool cone(const GateData&data,U v,U depth,int polarity,std::set<int32_t>&result){if(result.size()>64)return false;result.insert(int32_t(v)*polarity);auto it=data.gates.find(v);if(depth==0||it==data.gates.end())return true;if(it->second.ambiguous)return false;const auto&g=it->second;int orient=(g.z>0?1:-1)*polarity;for(auto l:{g.a,g.b})if(!cone(data,U(std::abs(l)),depth-1,orient*(l>0?1:-1),result))return false;return true;}
inline ta100::Block majority(const ta100::CNF&f,Budget&budget){std::vector<std::array<int32_t,3>> clauses;Q work=0;for(U cid=0;cid<f.clauses.size();++cid)if(!f.tautological[cid]&&f.clauses[cid].size()==3){const auto&c=f.clauses[cid];clauses.push_back({c[0],c[1],c[2]});if(clauses.size()>500000||(++work%4096==0&&budget.done()))return limited("graph_majority_gate_coverage","ternary index cap",work);}std::sort(clauses.begin(),clauses.end());clauses.erase(std::unique(clauses.begin(),clauses.end()),clauses.end());std::map<int32_t,std::set<std::pair<int32_t,int32_t>>> by_output;
 for(auto c:clauses){auto dual=c;for(auto&x:dual)x=-x;std::sort(dual.begin(),dual.end());if(!std::binary_search(clauses.begin(),clauses.end(),dual))continue;for(U j=0;j<3;++j){int32_t a=-c[(j+1)%3],b=-c[(j+2)%3];if(a>b)std::swap(a,b);by_output[c[j]].insert({a,b});}if(++work>1000000||((work&4095)==0&&budget.done()))return limited("graph_majority_gate_coverage","majority candidate index cap",work);}
 std::set<U> outputs;for(auto&item:by_output){std::map<int32_t,std::set<int32_t>> adj;for(auto edge:item.second)adj[edge.first].insert(edge.second),adj[edge.second].insert(edge.first);bool found=false;for(const auto&edge:item.second){int32_t a=edge.first,b=edge.second;for(auto c:adj[a])if(c>b&&std::abs(a)!=std::abs(b)&&std::abs(a)!=std::abs(c)&&std::abs(b)!=std::abs(c)&&adj[b].count(c)){found=true;break;}if(++work>1200000||((work&4095)==0&&budget.done()))return limited("graph_majority_gate_coverage","majority join cap",work);if(found)break;}if(found)outputs.insert(std::abs(item.first));}
 return ta100::fraction("graph_majority_gate_coverage",outputs.size(),f.active_variables,work);}
inline std::vector<ta100::Block> graph30(const ta100::CNF&f,double seconds){Budget budget(seconds);double setup=ta100::cpu_now();Small s=small_incidence(f,budget);if(s.complete)distances(s);Small p;if(s.complete&&!budget.done())p=primal(f,s,budget);GateData data;if(!budget.done())data=gates(f,budget);double setup_cpu=ta100::cpu_now()-setup;std::vector<ta100::Block>out;
 auto run=[&](std::string key,auto op){double t=ta100::cpu_now();auto b=budget.done()?limited(key,"module CPU budget exhausted"):op();b.cpu_s=ta100::cpu_now()-t;out.push_back(b);};
 run("graph_laminarity",[&](){if(!s.complete)return limited("graph_laminarity","sample incomplete");auto edges=hyperedges(s);Q crossing=0,tested=0;for(U a=0;a<edges.size();++a)for(U b=a+1;b<edges.size();++b){++tested;crossing+=(edges[a]&edges[b]).any()&&(edges[a]&~edges[b]).any()&&(edges[b]&~edges[a]).any();}return ta100::fraction("graph_laminarity",crossing,tested,tested);});
 run("graph_shattering",[&](){if(!s.complete)return limited("graph_shattering","sample incomplete");auto vs=vertices(s,true);auto edges=hyperedges(s);Q tested=0,found=0;for(U a=0;a<vs.size();++a)for(U b=a+1;b<vs.size();++b)for(U c=b+1;c<vs.size();++c){std::bitset<8>seen;for(const auto&e:edges)seen.set(U(e[vs[a]])+2*U(e[vs[b]])+4*U(e[vs[c]]));found+=seen.all();if(++tested==64)return ta100::fraction("graph_shattering",found,tested,tested*edges.size());}return ta100::fraction("graph_shattering",found,tested,tested*edges.size());});
 run("graph_cutrank",[&](){if(!s.complete)return limited("graph_cutrank","sample incomplete");U N=s.size();if(N<2)return numeric("graph_cutrank",NAN);long double sum=0;for(U seed=0;seed<16;++seed){auto order=vertices(s);std::sort(order.begin(),order.end(),[&](U a,U b){return mix(Q(a)+Q(seed)*257)<mix(Q(b)+Q(seed)*257);});Bits right;for(U j=N/2;j<N;++j)right.set(order[j]);std::vector<Bits> rows;for(U j=0;j<N/2;++j)rows.push_back(s.a[order[j]]&right);sum+=double(binary_rank(rows,N))/std::min<U>(N/2,N-N/2);}return numeric("graph_cutrank",double(sum/16),16*N*N);});
 run("graph_chordality",[&](){if(!p.complete)return limited("graph_chordality","primal sample incomplete");U N=p.size();Bits selected;std::array<U,128>score{};Q tested=0,bad=0;for(U step=0;step<N;++step){U chosen=N;for(U u=0;u<N;++u)if(!selected[u]&&(chosen==N||score[u]>score[chosen]))chosen=u;Bits before=p.a[chosen]&selected;if(before.count()>=2){++tested;bool clique=true;for(U v=0;v<N;++v)if(before[v]&&((before&~p.a[v]).count()>1))clique=false;bad+=!clique;}selected.set(chosen);for(U v=0;v<N;++v)if(p.a[chosen][v]&&!selected[v])++score[v];}return ta100::fraction("graph_chordality",bad,tested,N*N);});
 run("graph_hyperbolicity",[&](){if(!s.complete)return limited("graph_hyperbolicity","sample incomplete");U N=s.size();if(N<4)return numeric("graph_hyperbolicity",NAN);int diam=0;for(const auto&row:s.distance)for(int d:row)diam=std::max(diam,d);double delta=0;Q tested=0;for(U attempt=0;attempt<1024&&tested<128;++attempt){std::array<U,4> v{};for(U j=0;j<4;++j)v[j]=U(mix(Q(attempt)*4+j)%N);std::set<U> unique(v.begin(),v.end());if(unique.size()<4)continue;std::array<int,3>sums{{s.distance[v[0]][v[1]]+s.distance[v[2]][v[3]],s.distance[v[0]][v[2]]+s.distance[v[1]][v[3]],s.distance[v[0]][v[3]]+s.distance[v[1]][v[2]]}};bool valid=true;for(U a:v)for(U b:v)valid&=s.distance[a][b]>=0;if(!valid)continue;std::sort(sums.begin(),sums.end());delta=std::max(delta,(sums[2]-sums[1])/2.);++tested;}return numeric("graph_hyperbolicity",tested&&diam?delta/diam:NAN,tested);});
 run("graph_majority_gate_coverage",[&](){return majority(f,budget);});
 run("graph_reconvergence",[&](){if(!data.complete)return limited("graph_reconvergence","gate index incomplete");Q tested=0,found=0;for(const auto&item:data.gates)if(!item.second.ambiguous){std::set<int32_t>a,b;if(!cone(data,std::abs(item.second.a),2,1,a)||!cone(data,std::abs(item.second.b),2,1,b))continue;std::set<U> raw;for(auto l:a)raw.insert(std::abs(l));bool common=false;for(auto l:b)common|=raw.count(std::abs(l));++tested;found+=common;}return ta100::fraction("graph_reconvergence",found,tested,tested*64);});
 run("graph_gate_output_direction",[&](){if(!data.complete)return limited("graph_gate_output_direction","gate index incomplete");int64_t signed_count=0;Q count=0;for(const auto&item:data.gates)if(!item.second.ambiguous)signed_count+=item.second.z>0?1:-1,++count;return ta100::fraction("graph_gate_output_direction",signed_count,count,count);});
 run("graph_gate_ambiguity",[&](){if(!data.complete)return limited("graph_gate_ambiguity","gate index incomplete");return ta100::fraction("graph_gate_ambiguity",data.ambiguous,data.gates.size(),data.matches);});
 run("graph_gate_congruence",[&](){if(!data.complete)return limited("graph_gate_congruence","gate index incomplete");std::unordered_map<Q,U>classes;Q count=0;for(const auto&item:data.gates)if(!item.second.ambiguous){++classes[pairkey(code(item.second.a),code(item.second.b))];++count;}return ta100::fraction("graph_gate_congruence",count-classes.size(),count,count);});
 if(!out.empty()){out[0].cpu_s+=setup_cpu;out[0].reason+="; shared_incidence_sample_nodes="+std::to_string(s.size())+"; shared_sample_variables="+std::to_string(vertices(s,true).size())+"; original_active_variables="+std::to_string(f.active_variables)+"; shared_sample_work="+std::to_string(s.work);}return out;}
