struct LocalTable{U arity;std::vector<uint8_t> truth;};
struct LocalData{std::vector<LocalTable> tables;bool complete=true;Q work=0;};
inline LocalData local_tables(const ta100::CNF&f,Budget&budget){LocalData result;for(U cid=0;cid<f.clauses.size();++cid)if(!f.tautological[cid]&&f.clauses[cid].empty())return result;std::set<std::pair<Q,std::vector<U>>> chosen;
 for(U cid=0;cid<f.clauses.size();++cid)if(!f.tautological[cid]&&f.clauses[cid].size()>=3&&f.clauses[cid].size()<=4){std::vector<U> vars;for(auto l:f.clauses[cid])vars.push_back(std::abs(l));std::sort(vars.begin(),vars.end());Q h=0x31415926;for(U v:vars)h=mix(h^v);auto item=std::make_pair(h,vars);if(chosen.size()<64||item<*chosen.rbegin()){chosen.insert(item);if(chosen.size()>64)chosen.erase(std::prev(chosen.end()));}if((++result.work&8191)==0&&budget.done()){result.complete=false;return result;}}
 std::vector<U> stamp(f.clauses.size(),UINT32_MAX);U token=0;for(const auto&entry:chosen){const auto&vars=entry.second;std::vector<const ta100::Clause*> clauses;for(U v:vars)for(const auto*occ:{&f.pos[v],&f.neg[v]})for(U cid:*occ){if(++result.work>2000000||((result.work&8191)==0&&budget.done())){result.complete=false;return result;}if(stamp[cid]==token)continue;stamp[cid]=token;if(f.clauses[cid].size()>vars.size())continue;bool subset=true;for(auto l:f.clauses[cid])subset&=std::binary_search(vars.begin(),vars.end(),U(std::abs(l)));if(subset)clauses.push_back(&f.clauses[cid]);}
  LocalTable table{U(vars.size()),std::vector<uint8_t>(1U<<vars.size(),1)};for(U row=0;row<table.truth.size();++row)for(const auto*clause:clauses){bool satisfied=false;for(auto l:*clause){U j=U(std::lower_bound(vars.begin(),vars.end(),U(std::abs(l)))-vars.begin());satisfied|=bool((row>>j)&1)==(l>0);if(++result.work>2000000||((result.work&8191)==0&&budget.done())){result.complete=false;return result;}}if(!satisfied){table.truth[row]=0;break;}}result.tables.push_back(std::move(table));++token;}return result;}
inline U algebraic_degree(std::vector<uint8_t> truth,U arity){for(U j=0;j<arity;++j)for(U mask=0;mask<truth.size();++mask)if(mask&(1U<<j))truth[mask]^=truth[mask^(1U<<j)];U degree=0;for(U mask=0;mask<truth.size();++mask)if(truth[mask])degree=std::max<U>(degree,__builtin_popcount(mask));return degree;}
inline bool constant(const std::vector<uint8_t>&t){return std::all_of(t.begin(),t.end(),[&](uint8_t x){return x==t.front();});}
inline std::vector<uint8_t> restrict_table(const std::vector<uint8_t>&t,U arity,U variable,U value){std::vector<uint8_t> out(1U<<(arity-1));for(U row=0;row<out.size();++row){U low=row&((1U<<variable)-1),high=row>>variable;out[row]=t[low|(value<<variable)|(high<<(variable+1))];}return out;}
inline U canal_depth(const std::vector<uint8_t>&truth,U arity){if(!arity||constant(truth))return 0;U best=0;for(U v=0;v<arity;++v)for(U value=0;value<2;++value){auto side=restrict_table(truth,arity,v,value);if(constant(side))best=std::max(best,1+canal_depth(restrict_table(truth,arity,v,1-value),arity-1));}return best;}
inline bool symmetric_after_input_flips(const std::vector<uint8_t>&t,U arity){for(U flip=0;flip<(1U<<arity);++flip){std::array<int,5> by_weight{{-1,-1,-1,-1,-1}};bool same=true;for(U row=0;row<t.size();++row){U w=__builtin_popcount(row);int value=t[row^flip];if(by_weight[w]<0)by_weight[w]=value;else if(by_weight[w]!=value){same=false;break;}}if(same)return true;}return false;}
inline bool ite_function(const std::vector<uint8_t>&t,U arity){if(arity!=3)return false;for(U selector=0;selector<3;++selector)for(U a=0;a<3;++a)if(a!=selector)for(U b=0;b<3;++b)if(b!=selector&&b!=a)for(U flips=0;flips<4;++flips){bool same=true;for(U row=0;row<8;++row){bool value=((row>>selector)&1)?bool((row>>a)&1)^bool(flips&1):bool((row>>b)&1)^bool(flips&2);if(value!=bool(t[row])){same=false;break;}}if(same)return true;}return false;}
inline bool other_functional(const LocalTable&t){U N=t.arity;if(constant(t.truth))return false;for(U output=0;output<N;++output){std::vector<uint8_t>function(1U<<(N-1));bool total=true;for(U row=0;row<function.size();++row){U low=row&((1U<<output)-1),high=row>>output;U mask=low|(high<<(output+1));bool a=t.truth[mask],b=t.truth[mask|(1U<<output)];if(a==b){total=false;break;}function[row]=b;}if(total&&algebraic_degree(function,N-1)>1&&!symmetric_after_input_flips(function,N-1)&&!ite_function(function,N-1))return true;}return false;}
struct CCData{std::vector<double> zero,one;std::vector<U>order;std::vector<std::vector<U>> consumers;};
inline CCData controllability(const ta100::CNF&f,const GateData&data,Budget&budget){CCData cc;cc.zero.assign(f.n+1,NAN);cc.one.assign(f.n+1,NAN);cc.consumers.resize(f.n+1);std::vector<U>pending(f.n+1);std::vector<uint8_t>isgate(f.n+1);for(const auto&item:data.gates)isgate[item.first]=1;
 std::deque<U>q;for(U v=1;v<=f.n;++v)if(!isgate[v]&&(!f.pos[v].empty()||!f.neg[v].empty()))cc.zero[v]=cc.one[v]=1,q.push_back(v);
 for(const auto&item:data.gates)if(!item.second.ambiguous){U v=item.first;for(auto l:{item.second.a,item.second.b}){++pending[v];cc.consumers[std::abs(l)].push_back(v);}}
 while(!q.empty()){U u=q.front();q.pop_front();for(U v:cc.consumers[u])if(pending[v]&&--pending[v]==0){const auto&g=data.gates.at(v);double a0=g.a>0?cc.zero[std::abs(g.a)]:cc.one[std::abs(g.a)],a1=g.a>0?cc.one[std::abs(g.a)]:cc.zero[std::abs(g.a)],b0=g.b>0?cc.zero[std::abs(g.b)]:cc.one[std::abs(g.b)],b1=g.b>0?cc.one[std::abs(g.b)]:cc.zero[std::abs(g.b)];double z0=std::min(1e12,1+std::min(a0,b0)),z1=std::min(1e12,1+a1+b1);cc.zero[v]=g.z>0?z0:z1;cc.one[v]=g.z>0?z1:z0;cc.order.push_back(v);q.push_back(v);}if(budget.done())break;}return cc;}
inline int assignment_cost(const std::array<std::array<int,16>,16>&cost){constexpr int N=16;std::array<int,N+1>u{},v{},p{},way{};for(int i=1;i<=N;++i){p[0]=i;int j0=0;std::array<int,N+1>minv;minv.fill(1000000);std::array<bool,N+1>used{};do{used[j0]=true;int i0=p[j0],delta=1000000,j1=0;for(int j=1;j<=N;++j)if(!used[j]){int cur=cost[i0-1][j-1]-u[i0]-v[j];if(cur<minv[j])minv[j]=cur,way[j]=j0;if(minv[j]<delta)delta=minv[j],j1=j;}for(int j=0;j<=N;++j)if(used[j])u[p[j]]+=delta,v[j]-=delta;else minv[j]-=delta;j0=j1;}while(p[j0]);do{int j1=way[j0];p[j0]=p[j1];j0=j1;}while(j0);}return -v[0];}
inline ta100::Block betti(const Small&p,Budget&budget){U N=p.size();if(!p.complete)return limited("graph_betti1","primal sample incomplete");std::vector<std::vector<int>>index(N,std::vector<int>(N,-1));U E=0;for(U a=0;a<N;++a)for(U b=a+1;b<N;++b)if(p.a[a][b])index[a][b]=index[b][a]=E++;if(!E)return numeric("graph_betti1",NAN);U words=(E+63)/64,rank=0;std::vector<std::vector<Q>>basis(E);Q triangles=0,work=0;
 for(U a=0;a<N;++a)for(U b=a+1;b<N;++b)if(p.a[a][b])for(U c=b+1;c<N;++c)if(p.a[a][c]&&p.a[b][c]){if(++triangles>20000)return limited("graph_betti1","triangle cap",triangles);std::vector<Q> row(words);for(U edge:{U(index[a][b]),U(index[a][c]),U(index[b][c])})row[edge/64]^=Q(1)<<(edge%64);for(U word=0;word<words;++word)while(row[word]){U pivot=word*64+__builtin_ctzll(row[word]);if(basis[pivot].empty()){basis[pivot]=std::move(row);++rank;goto next_triangle;}for(U w=word;w<words;++w){row[w]^=basis[pivot][w];if(++work>2000000||((work&8191)==0&&budget.done()))return limited("graph_betti1","boundary elimination cap",work);}}next_triangle:;}
 Bits seen;U components=0;for(U start=0;start<N;++start)if(!seen[start]){++components;std::deque<U>q{start};seen.set(start);while(!q.empty()){U u=q.front();q.pop_front();for(U v=0;v<N;++v)if(p.a[u][v]&&!seen[v])seen.set(v),q.push_back(v);}}int64_t beta=int64_t(E)-N+components-rank;if(beta<0)return ta100::unavailable("graph_betti1","INVALID","negative homology dimension",work);return ta100::fraction("graph_betti1",beta,E,work);}
inline std::vector<ta100::Block> graph40(const ta100::CNF&f,double seconds){Budget budget(seconds);double setup=ta100::cpu_now();Small s=small_incidence(f,budget);if(s.complete)distances(s);Small p;if(s.complete&&!budget.done())p=primal(f,s,budget);auto label=partition(s);GateData data;if(!budget.done())data=gates(f,budget);CCData cc;if(data.complete&&!budget.done())cc=controllability(f,data,budget);double setup_cpu=ta100::cpu_now()-setup;std::vector<ta100::Block>out;
 auto run=[&](std::string key,auto op){double t=ta100::cpu_now();auto b=budget.done()?limited(key,"module CPU budget exhausted"):op();b.cpu_s=ta100::cpu_now()-t;out.push_back(b);};
 run("graph_controllability",[&](){if(!data.complete)return limited("graph_controllability","gate index incomplete");long double sum=0;Q count=0;for(U v:cc.order)if(std::isfinite(cc.zero[v])&&std::isfinite(cc.one[v]))sum+=(cc.one[v]-cc.zero[v])/(cc.one[v]+cc.zero[v]),++count;auto b=numeric("graph_controllability",count?double(sum/count):NAN,cc.order.size());b.count=count;b.denominator=data.gates.size();return b;});
 run("graph_observability",[&](){if(!data.complete)return limited("graph_observability","gate index incomplete");std::vector<double>co(f.n+1,INFINITY);for(U v:cc.order)if(cc.consumers[v].empty())co[v]=0;for(U cid=0;cid<f.clauses.size();++cid)if(!f.tautological[cid]&&!data.pool.count(f.clauses[cid]))for(auto l:f.clauses[cid])co[std::abs(l)]=0;for(auto it=cc.order.rbegin();it!=cc.order.rend();++it){U v=*it;const auto&g=data.gates.at(v);if(!std::isfinite(co[v]))continue;double a1=g.a>0?cc.one[std::abs(g.a)]:cc.zero[std::abs(g.a)],b1=g.b>0?cc.one[std::abs(g.b)]:cc.zero[std::abs(g.b)];co[std::abs(g.a)]=std::min(co[std::abs(g.a)],co[v]+b1+1);co[std::abs(g.b)]=std::min(co[std::abs(g.b)],co[v]+a1+1);}long double sum=0;Q count=0;for(U v:cc.order)if(std::isfinite(co[v]))sum+=co[v]/(co[v]+cc.zero[v]+cc.one[v]),++count;return numeric("graph_observability",count?double(sum/count):NAN,f.raw_literals);});
 run("graph_binate_cones",[&](){if(!data.complete)return limited("graph_binate_cones","gate index incomplete");Q tested=0,binate=0;for(const auto&item:data.gates)if(!item.second.ambiguous){std::set<int32_t>anc;if(!cone(data,item.first,2,1,anc))continue;bool both=false;for(auto l:anc)both|=anc.count(-l);++tested;binate+=both;}return ta100::fraction("graph_binate_cones",binate,tested,tested*64);});
 // Execute this cheap independent descriptor before the local-truth-table block.
 run("graph_sign_bundling",[&](){std::array<std::array<Q,65>,65>counts{};std::array<Q,65>total{};Q eligible=0,pos=0,lits=0;for(U cid=0;cid<f.clauses.size();++cid)if(!f.tautological[cid]){U k=f.clauses[cid].size();if(!k||k>64)continue;U np=0;for(auto l:f.clauses[cid])np+=l>0;++counts[k][np];++total[k];++eligible;pos+=np;lits+=k;}if(!eligible)return numeric("graph_sign_bundling",NAN);double probability=double(pos)/lits;long double kl=0;if(probability>0&&probability<1)for(U k=1;k<=64;++k)if(total[k])for(U j=0;j<=k;++j)if(counts[k][j]){long double logq=std::lgamma(double(k)+1)-std::lgamma(double(j)+1)-std::lgamma(double(k-j)+1)+j*std::log(probability)+(k-j)*std::log1p(-probability);kl+=double(counts[k][j])/eligible*(std::log(double(counts[k][j])/total[k])-logq);}auto b=numeric("graph_sign_bundling",std::max(0.,double(kl)),f.raw_literals);b.count=eligible;b.denominator=f.raw_clauses-f.tautological_clauses;return b;});
 double local_start=ta100::cpu_now();LocalData local;if(!budget.done())local=local_tables(f,budget);else local.complete=false;double local_cpu=ta100::cpu_now()-local_start;
 run("graph_other_functional",[&](){if(!local.complete)return limited("graph_other_functional","local table cap",local.work);Q eligible=0,found=0;for(const auto&t:local.tables)if(!constant(t.truth)){++eligible;found+=other_functional(t);}return ta100::fraction("graph_other_functional",found,eligible,local.work);});out.back().cpu_s+=local_cpu;
 run("graph_canalizing_depth",[&](){if(!local.complete)return limited("graph_canalizing_depth","local table cap",local.work);long double sum=0;Q eligible=0;for(const auto&t:local.tables)if(!constant(t.truth))sum+=double(canal_depth(t.truth,t.arity))/t.arity,++eligible;return numeric("graph_canalizing_depth",eligible?double(sum/eligible):NAN,local.work);});
 run("graph_anf_degree",[&](){if(!local.complete)return limited("graph_anf_degree","local table cap",local.work);long double sum=0;Q eligible=0;for(const auto&t:local.tables)if(!constant(t.truth)){U degree=algebraic_degree(t.truth,t.arity);if(degree>1)sum+=double(degree)/t.arity,++eligible;}return numeric("graph_anf_degree",eligible?double(sum/eligible):NAN,local.work);});
 run("graph_community_polarity",[&](){if(!s.complete)return limited("graph_community_polarity","sample incomplete");std::array<long double,128>positive{},negative{};Q total=0,count=0;for(U u=0;u<s.size();++u)if(s.variable[u]){U v=s.original[u]+1;positive[label[u]]+=f.pos[v].size();negative[label[u]]+=f.neg[v].size();total+=f.pos[v].size()+f.neg[v].size();++count;}if(!total)return numeric("graph_community_polarity",NAN);long double global=0;for(U j=0;j<128;++j)global+=positive[j]-negative[j];global/=total;long double variance=0;for(U j=0;j<128;++j)if(positive[j]+negative[j]){long double mass=positive[j]+negative[j],bias=(positive[j]-negative[j])/mass;variance+=mass/total*(bias-global)*(bias-global);}auto b=numeric("graph_community_polarity",double(variance),total);b.count=count;b.denominator=f.active_variables;return b;});
 run("graph_transport_curvature",[&](){if(!s.complete)return limited("graph_transport_curvature","sample incomplete");U N=s.size();Q tested=0;long double sum=0;for(U a=0;a<N;++a)for(U b=a+1;b<N;++b)if(s.a[a][b]){std::vector<U>na,nb;for(U u=0;u<N;++u){if(s.a[a][u])na.push_back(u);if(s.a[b][u])nb.push_back(u);}std::array<U,16>left{},right{};for(U j=0;j<16;++j)left[j]=j<8?a:na[mix(Q(a)*257+j)%na.size()],right[j]=j<8?b:nb[mix(Q(b)*257+j)%nb.size()];std::array<std::array<int,16>,16>cost{};for(U i=0;i<16;++i)for(U j=0;j<16;++j)cost[i][j]=s.distance[left[i]][right[j]];sum+=1.-assignment_cost(cost)/16.;if(++tested==32)return numeric("graph_transport_curvature",double(sum/tested),tested*4096);}return numeric("graph_transport_curvature",tested?double(sum/tested):NAN,tested*4096);});
 run("graph_betti1",[&](){return betti(p,budget);});
 if(!out.empty()){out[0].cpu_s+=setup_cpu;out[0].reason+="; shared_incidence_sample_nodes="+std::to_string(s.size())+"; shared_sample_variables="+std::to_string(vertices(s,true).size())+"; original_active_variables="+std::to_string(f.active_variables)+"; shared_sample_work="+std::to_string(s.work);}return out;}
